SELECT ?item ?class ?en ?sv (GROUP_CONCAT(DISTINCT ?sym; separator=" | ") AS ?syms) WHERE {
  VALUES ?class { wd:Q223662 wd:Q208469 wd:Q181508 }
  ?item wdt:P31 ?class .
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item wdt:P5061 ?sym }
} GROUP BY ?item ?class ?en ?sv ORDER BY ?class ?en

SELECT ?name ?item ?sv (GROUP_CONCAT(DISTINCT CONCAT(STR(?sym), "@", LANG(?sym)); separator=" | ") AS ?syms) (GROUP_CONCAT(DISTINCT STR(?cls); separator=" ") AS ?classes) WHERE {
  VALUES ?name { "metre" "kilogram" "second" "ampere" "kelvin" "mole" "candela"
    "radian" "steradian" "hertz" "newton" "pascal" "joule" "watt" "coulomb" "volt" "farad" "ohm"
    "siemens" "weber" "tesla" "henry" "degree Celsius" "lumen" "lux" "becquerel" "gray" "sievert" "katal" }
  ?item rdfs:label ?l .
  FILTER(STR(?l) = ?name && LANG(?l) = "en")
  ?item wdt:P5061 ?sym .
  ?item wdt:P31 ?cls .
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
} GROUP BY ?name ?item ?sv ORDER BY ?name

SELECT ?name ?item ?sv (GROUP_CONCAT(DISTINCT CONCAT(STR(?sym), "@", LANG(?sym)); separator=" | ") AS ?syms) WHERE {
  VALUES ?name { "metre"@en "kilogram"@en "second"@en "ampere"@en "kelvin"@en "mole"@en "candela"@en
    "radian"@en "steradian"@en "hertz"@en "newton"@en "pascal"@en "joule"@en "watt"@en "coulomb"@en "volt"@en "farad"@en "ohm"@en
    "siemens"@en "weber"@en "tesla"@en "henry"@en "degree Celsius"@en "lumen"@en "lux"@en "becquerel"@en "gray"@en "sievert"@en "katal"@en }
  ?item rdfs:label ?name .
  ?item wdt:P5061 ?sym .
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
} GROUP BY ?name ?item ?sv ORDER BY ?name

SELECT ?name ?item ?itemLabel ?sv ?cls ?clsLabel (GROUP_CONCAT(DISTINCT ?sym; separator=" | ") AS ?syms) WHERE {
  VALUES ?name { "quetta"@en "ronna"@en "yotta"@en "zetta"@en "exa"@en "peta"@en "tera"@en "giga"@en "mega"@en "kilo"@en
    "hecto"@en "deca"@en "deci"@en "centi"@en "milli"@en "micro"@en "nano"@en "pico"@en "femto"@en "atto"@en
    "zepto"@en "yocto"@en "ronto"@en "quecto"@en }
  ?item rdfs:label ?name ; wdt:P31 ?cls .
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item wdt:P5061 ?sym }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} GROUP BY ?name ?item ?itemLabel ?sv ?cls ?clsLabel ORDER BY ?name

SELECT ?item ?en ?sv (GROUP_CONCAT(DISTINCT ?sym; separator=" | ") AS ?syms) (GROUP_CONCAT(DISTINCT STR(?num); separator=" | ") AS ?nums) (GROUP_CONCAT(DISTINCT CONCAT(STR(?svAlt)); separator=" | ") AS ?svAlts) WHERE {
  ?item wdt:P31 wd:Q131299 .
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item skos:altLabel ?svAlt FILTER(LANG(?svAlt) = "sv") }
  OPTIONAL { ?item wdt:P5061 ?sym }
  OPTIONAL { ?item wdt:P1181 ?num }
} GROUP BY ?item ?en ?sv ORDER BY ?en

