    wd:Q33680 wd:Q177612 wd:Q39369 wd:Q12438 wd:Q44395 wd:Q25269 wd:Q25236 wd:Q25406 wd:Q25250
    wd:Q131255 wd:Q47083 wd:Q169893 wd:Q170804 wd:Q163343 wd:Q163354 wd:Q25267 wd:Q484092
    wd:Q179836 wd:Q102573 wd:Q190095 wd:Q103246 wd:Q208634 }
  OPTIONAL { ?unit wdt:P111 ?q .
    OPTIONAL { ?q rdfs:label ?qEn FILTER(LANG(?qEn) = "en") }
